   Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);go.transform.localScale*=height/Mathf.Max(.01f,bounds.size.y);bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float y=TerrainScaleBounds.BackdropHeight(surface,x,z);go.transform.position+=new Vector3(x,y,z)-new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);
   bounds=renderers[0].bounds;foreach(var r in renderers){bounds.Encapsulate(r.bounds);r.sharedMaterials=r.sharedMaterials.Select(m=>MaterialCopy(m,far)).ToArray();r.shadowCastingMode=height>8&&!far&&used.Sum(u=>u.instances)%3==0?ShadowCastingMode.On:ShadowCastingMode.Off;r.receiveShadows=true;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.BatchingStatic);}
