  static Texture2D GroundTexture(string source,string name,int max){string dest=Root+"/Textures/"+name+".png";Require(AssetDatabase.CopyAsset(source,dest),"Ground texture missing");var imp=(TextureImporter)AssetImporter.GetAtPath(dest);imp.maxTextureSize=max;imp.mipmapEnabled=true;imp.anisoLevel=4;imp.textureCompression=TextureImporterCompression.Compressed;imp.crunchedCompression=false;imp.isReadable=false;var p=imp.GetPlatformTextureSettings("Standalone");p.overridden=true;p.maxTextureSize=max;p.format=TextureImporterFormat.Automatic;p.textureCompression=TextureImporterCompression.Compressed;imp.SetPlatformTextureSettings(p);imp.SaveAndReimport();var t=AssetDatabase.LoadAssetAtPath<Texture2D>(dest);Require(t.width<=max&&t.height<=max,"Ground texture cap");return t;}
  static bool Spaced(List<Vector2> taken,Vector2 p,float distance){return taken.All(q=>(q-p).sqrMagnitude>distance*distance);}
