   string pine=PT("Trees/PT_Pine_Tree_03_green"),fir=SC("Tree/Fir/Mobile_forestpack_tree_fir_tall"),leaf=SC("Tree/Leaf/Normal/Mobile_forestpack_tree_1_leaf_1"),rock=SC("Stone/Mobile_forestpack_stone_large_1"),moss=PP("PP_Rock_Moss_Grown_11");
   // Poisson-like thinning of a noise-shaped perimeter, not a repeated ring of identical islands.
   var trees=new List<Vector2>();for(int attempt=0;attempt<14000&&trees.Count<260;attempt++){
    var p=new Vector2(Rand(-380,380),Rand(-370,390));if(Mathf.Abs(p.x)<266&&Mathf.Abs(p.y)<249)continue;if(Mathf.Abs(p.x)>355&&Mathf.Abs(p.y)>340)continue;
    float density=.28f+.58f*Mathf.PerlinNoise(p.x*.014f+32,p.y*.014f+71);if(p.y< -270)density*=.55f;if(Mathf.Abs(p.y-16*Mathf.Sin(p.x/54))<23&&Mathf.Abs(p.x)>245)continue;
