  static void CapturePreview(Camera camera,WarSandboxBattlefieldCatalog catalog){var rt=new RenderTexture(1280,720,24);var image=new Texture2D(1280,720,TextureFormat.RGB24,false);var old=camera.targetTexture;var active=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(Root+"/Preview.png",image.EncodeToPNG());File.WriteAllBytes(Logs+"/editor-overview.png",image.EncodeToPNG());}finally{camera.targetTexture=old;RenderTexture.active=active;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(image);}AssetDatabase.ImportAsset(Root+"/Preview.png");var imp=(TextureImporter)AssetImporter.GetAtPath(Root+"/Preview.png");imp.maxTextureSize=512;imp.SaveAndReimport();foreach(var e in catalog.entries)e.preview=AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Preview.png");EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();}

  static void MoveVisual(GameObject go,float x,float z,float height,float yaw,bool mountain){var rr=go.GetComponentsInChildren<Renderer>();go.transform.rotation=Quaternion.Euler(0,yaw,0);var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);float factor=height/b.size.y;go.transform.localScale*=factor;if(mountain){var v=go.transform.localScale;go.transform.localScale=new Vector3(v.x*1.7f,v.y,v.z*1.5f);}b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);go.transform.position+=new Vector3(x,TerrainScaleBounds.BackdropHeight(surface,x,z)-height*(mountain?.24f:.07f),z)-new Vector3(b.center.x,b.min.y,b.center.z);b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);Require(!(b.min.x<242&&b.max.x> -242&&b.min.z<220&&b.max.z> -220),"Refined landmark enters playable area");if(mountain)foreach(var r in rr)foreach(var m in r.sharedMaterials){Require(AssetDatabase.GetAssetPath(m).StartsWith(Root+"/"),"Refuse shared source edit");m.SetFloat("_MountainGrade",1);EditorUtility.SetDirty(m);}}
  public static void Refine(){Require(!File.Exists(Logs+"/refine.json"),"Refine already done");File.Copy(Battle,Logs+"/draft01-scene.unity",false);File.Copy(Logs+"/editor-overview.png",Logs+"/draft01-overview.png",false);var scene=EditorSceneManager.OpenScene(Battle,OpenSceneMode.Single);Require(Find<MassEngineManager>(scene).TryGetTerrainContext(out surface,out _,out var error),error);rng=new System.Random(2006);var ridge=GameObject.Find("Rock shelves and far ridgeline").transform;Require(ridge.childCount==40,"Unexpected landmark layout");var west=new[]{new Vector2(-306,-146),new Vector2(-318,25),new Vector2(-308,162)};for(int k=0;k<18;k++){var p=west[k/6];int n=k%6;float a=n*2.4f+Rand(-.2f,.2f),d=n==0?0:Rand(6,17);MoveVisual(ridge.GetChild(k).gameObject,p.x+Mathf.Cos(a)*d,p.y+Mathf.Sin(a)*d,n==0?Rand(11,14):Rand(4,9),Rand(0,360),false);}var north=new[]{new Vector2(130,289),new Vector2(250,291)};for(int k=0;k<14;k++){var p=north[k/7];int n=k%7;float a=n*2.4f,d=n==0?0:Rand(6,18);MoveVisual(ridge.GetChild(18+k).gameObject,p.x+Mathf.Cos(a)*d,p.y+Mathf.Sin(a)*d*.65f,n==0?Rand(9,12):Rand(3,8),Rand(0,360),false);}var peaks=new[]{new Vector3(-355,50,555),new Vector3(-220,65,598),new Vector3(-72,92,620),new Vector3(73,74,598),new Vector3(230,59,555),new Vector3(372,47,530),new Vector3(-650,60,150),new Vector3(650,58,-150)};for(int k=0;k<8;k++){var p=peaks[k];MoveVisual(ridge.GetChild(32+k).gameObject,p.x,p.z,p.y,Rand(0,360),true);}EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();CapturePreview(Camera.main,Find<WarSandboxRuntimeDeployment>(scene).battlefieldCatalog);File.WriteAllText(Logs+"/refine.json","{\"passed\":true,\"landmarksRepositioned\":40,\"groundColorGraded\":true,\"playableBoundsPreserved\":true}");}
